<template>
  <v-container class="py-5">
    <v-card>
      <v-card-title>
        Pending New Registration Applications
        <v-spacer></v-spacer>
      </v-card-title>
      <v-card-title>
        <v-select
          :items="status"
          v-model="search.financestatus"
          label="Finance Director Status"
          outlined
          dense
          class="ma-2"
          hide-details
          clearable
          @change="buildTerms()"
          @click:clear="clearSearch('financestatus')"
        ></v-select>
        <v-select
          :items="status"
          v-model="search.taalimstatus"
          label="Taalim Director Status"
          outlined
          dense
          class="ma-2"
          hide-details
          clearable
          @change="buildTerms()"
          @click:clear="clearSearch('taalimstatus')"
        ></v-select>
        <v-text-field
          label="Name"
          class="ma-2"
          v-model="search.name"
          dense
          outlined
          hide-details
          clearable
          @change="buildTerms()"
          @click:clear="clearSearch('name')"
        />
      </v-card-title>
      <v-card-subtitle v-if="error_message" class="white--text error">{{
        error_message
      }}</v-card-subtitle>
      <v-card-text>
        <v-data-table
          style="cursor: pointer"
          :headers="headers"
          :items="results"
          item-key="id"
          :options.sync="options"
          :server-items-length="total"
          :footer-props="{
            'items-per-page-text': $t('App.hardcoded-texts.tableText'),
            'items-per-page-options': [5, 10, 20, 50],
          }"
          :loading="loading"
          class="elevation-1"
          @click:row="clickIt"
        >
          <template v-slot:item.financeStatus="{ item }">
            <v-chip :color="getColor(item.financeStatus)" dark>
              {{ item.financeStatus }}
            </v-chip>
          </template>
          <template v-slot:item.taalimStatus="{ item }">
            <v-chip :color="getColor(item.taalimStatus)" dark>
              {{ item.taalimStatus }}
            </v-chip>
          </template>
        </v-data-table>
      </v-card-text>
    </v-card>
  </v-container>
</template>

<script>
export default {
  data: function() {
    return {
      search: {
        name: "",
        taalimstatus: "",
        financestatus: "",
      },
      debug: "",
      terms: {},
      headers: [
        {
          text: "Name",
          value: "name",
        },
        {
          text: "Date of Birth",
          value: "birthDate",
        },
        {
          text: "Gender",
          value: "gender",
        },
        {
          text: "Nationality",
          value: "nationality",
        },
        {
          text: "Phone",
          value: "phone",
        },
        {
          text: "Finance Director",
          value: "financeStatus",
        },
        {
          text: "Taalim Director",
          value: "taalimStatus",
        },
      ],
      status: [
        {
          text: "Pending",
          value: "pending",
        },
        {
          text: "Approved",
          value: "approved",
        },
        {
          text: "Reject",
          value: "reject",
        },
      ],
      results: [],
      options: { itemsPerPage: 10 },
      loading: false,
      total: 0,
      prevPage: -1,
      link: [],
      error_message: null,
      update_again: { rerun: false, restart: false },
    };
  },
  watch: {
    options: {
      handler() {
        this.getData();
      },
      deep: true,
    },
  },
  mounted: function() {
    this.getData(true);
  },
  methods: {
    clearSearch: function(field) {
      this.search[field] = "";
      this.buildTerms();
    },
    clickIt: function(record) {
      this.$router.push(
        "/custom/new_registration_view?path=/itsf&id=" + record.id
      );
    },
    checkRerun() {
      if (!this.loading && this.update_again.rerun) {
        this.getData(this.update_again.restart);
        this.update_again = { rerun: false, restart: false };
      }
    },
    async buildTerms() {
      this.terms = {};
      if (this.search.name) {
        this.terms["name"] = this.search.name;
      }
      if (this.search.financestatus) {
        this.terms["newappfinancestatus"] = this.search.financestatus;
      }
      if (this.search.taalimstatus) {
        this.terms["newapptaalimstatus"] = this.search.taalimstatus;
      }
      this.getData(true);
    },
    getColor(status) {
      if (status === "Pending") {
        return "warning";
      } else if (status === "Rejected") {
        return "error";
      } else if (status === "Approved") {
        return "success";
      }
      return "grey";
    },
    getData(restart) {
      //console.log("getting data",restart)
      if (this.loading) {
        this.update_again.rerun = true;
        this.update_again.restart = this.update_again.restart || restart;
        return;
      }
      this.loading = true;
      this.error_message = null;
      let url = "";
      let count = this.options.itemsPerPage || 10;
      if (restart) this.options.page = 1;
      if (this.options.page > 1) {
        if (this.options.page === this.prevPage - 1) {
          url = this.link.find((link) => link.relation === "previous").url;
        } else if (this.options.page === this.prevPage + 1) {
          url = this.link.find((link) => link.relation === "next").url;
        }
        // Should make this smarter to keep the _getpages parameter,
        // but the issue is with tracking permissions on the resource
        url = url.replace(
          "/fhir?",
          "/site/student/getRegistrationApplications?"
        );
        url = url.substring(
          url.indexOf("/site/student/getRegistrationApplications")
        );
        //some of the hapi instances requires _total=accurate to always be available for them to return total resources
        if (url.indexOf("_sort=-_lastUpdated") === -1) {
          url = url + "&_sort=-_lastUpdated";
        }
        if (url.indexOf("_total=accurate") === -1) {
          url = url + "&_total=accurate";
        }
      }
      if (url === "") {
        let sort = "";
        for (let idx in this.options.sortBy) {
          if (sort) {
            sort += ",";
          }
          if (this.options.sortDesc[idx]) {
            sort += "-";
          }
          sort += this.options.sortBy[idx];
        }
        url =
          "/site/student/getRegistrationApplications?_count=" +
          count +
          "&regtype:not=shortcourse&_profile=http://ihris.org/fhir/StructureDefinition/itsf-registration-application&_sort=-_lastUpdated&_total=accurate";
        this.debug = url;
      }
      let sTerms = Object.keys(this.terms);
      for (let term of sTerms) {
        if (Array.isArray(this.terms[term])) {
          if (this.terms[term].length > 0) {
            url += "&" + term + "=" + this.terms[term].join(",");
          }
        } else if (this.terms[term]) {
          url += "&" + term + "=" + this.terms[term];
        }
      }

      this.prevPage = this.options.page;
      fetch(url)
        .then((response) => {
          response
            .json()
            .then(async (data) => {
              this.results = [];
              if (data.total > 0) {
                this.link = data.link;
                this.results = data.data;
              }
              this.total = data.total;
              this.loading = false;
              this.checkRerun();
            })
            .catch((err) => {
              this.loading = false;
              this.error_message = "Unable to load results.";
              this.checkRerun();
              console.log(err);
            });
        })
        .catch((err) => {
          this.loading = false;
          this.error_message = "Unable to load results.";
          this.checkRerun();
          console.log(err);
        });
    },
  },
};
</script>
<style>
tbody tr:nth-of-type(even) {
  background-color: #e0f2f1;
}
</style>
